'use strict';
for(const p of RaceDrives.catalog)if(Ecology.profile(p.race).strict)Ecology.nativeDreams.push(...Object.values(p.paths));
RaceDrives.install();FaithWorld.install();
const BeliefUI=(()=>{
 const resourceLabel=s=>({roots:'ความชื้นและธาตุอาหาร',gel:'อาหารและกำลังแกน',shade:'ความมั่นคงของจุดยึด',quad:'กำลังและแหล่งอาหาร',fins:'อาหารและกระแสพัก',coil:'อาหารและเขตพัก',wings:'กำลังและแหล่งพัก'}[Ecology.profile(s).body]||'ความสมบูรณ์ของแหล่งถิ่น');
 function panel(s){const r=RaceDrives.ensure(s),p=RaceDrives.profile(s),f=FaithWorld.ensure(s),g=FaithWorld.god(f.chosen),a=f.active;return `<section class="panel belief-overview"><div class="belief-heading"><div><span class="eyebrow">สิ่งที่อยากเป็น · ${esc(RACES[s.race][0])}</span><h3>${esc(r.stance?p.paths[r.stance]:p.name)}</h3></div><button class="secondary" id="openRaceWays">เลือกทาง →</button></div>${RaceDrives.cashless(s)?`<div class="native-needs"><span>${resourceLabel(s)}</span><progress max="100" value="${r.resource}"></progress><b>${Math.round(r.resource)}</b></div>`:''}<button class="belief-faith-link" id="openFaith"><span class="faith-dot" style="--deity:${g?.colour||'#84917a'}"></span><span><strong>${g?esc(g.name):'ศรัทธาที่ยังเลือกได้'}</strong><small>${a?'มีคำขอจาก '+esc(g.deity)+' · บท '+(a.stage+1)+'/3':g?'ผู้มีตัวตนในโลกนี้ · ยังมีสิทธิ์ตั้งคำถาม':f.effects.length?'พิธีที่เคยเลือกยังส่งผลต่อโลก แม้ไม่ได้ผูกศรัทธาอยู่':'สำรวจเทพ ศาสดา และวิถีที่หลายเผ่ารับฟัง'}</small></span><span>↗</span></button></section>`}
 function bind(){if($('#openRaceWays'))$('#openRaceWays').onclick=ways;if($('#openFaith'))$('#openFaith').onclick=faith}
 function refresh(view){save();clock.reset();render();view()}
 function ways(){const s=state,r=RaceDrives.ensure(s),p=RaceDrives.profile(s),locked=s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<6;modal(`<section class="belief-dialog"><span class="eyebrow">${esc(RACES[s.race][0])} · ${esc(Ecology.profile(s).label)}</span><h2>${esc(p.name)}</h2><p>${esc(p.pressure)}</p><p class="belief-note">ถิ่นและร่างพาคุณมาถึงจุดนี้ ทางต่อไปยังเป็นของคุณ เปลี่ยนทิศได้ปีละครั้งโดยไม่มีแต้มจากการกดเลือก</p><div class="choices">${Object.entries(p.paths).map(([id,label])=>`<button class="choice" data-race-stance="${id}" ${locked||r.stance===id||r.lastChangeYear===WorldTimeline.year(s)?'disabled':''}><span class="num">${r.stance===id?'✓':'◇'}</span><span><b>${esc(label)}</b><small>${{inherit:'รับช่วงสิ่งที่เผ่าคาดหวัง',coexist:'หาวิธีอยู่ร่วมโดยรักษาร่างและถิ่น',self:'สร้างทางที่อาจต่างจากเผ่าของตน'}[id]}</small></span></button>`).join('')}</div>${RaceDrives.cashless(s)?`<h3>${resourceLabel(s)} · ${Math.round(r.resource)}/100</h3><p>ถิ่นนี้ดำรงชีวิตจากแหล่งอาหาร พลัง หรือจุดยึด เงินที่สะสมไว้ยังอยู่ แต่ไม่ได้ถูกตัดเป็นค่าเช่าหรือภาษีเมือง</p><div class="choices">${[['forage','สำรวจหาแหล่งดำรงชีวิต','แหล่งถิ่น +14 · สุขภาพ −1'],['claim','ประกาศเขตและขับผู้แย่งแหล่งพัก','แหล่งถิ่น +20 · สัมพันธ์ −3 · ผู้ถูกขับเสียพื้นที่'],['share','เว้นส่วนให้ผู้อื่นใช้ร่วม','แหล่งถิ่น −8 · สัมพันธ์ +3']].map(([id,label,hint])=>`<button class="choice" data-native-action="${id}" ${locked||r.actionQuarter===s.calendar.count||id==='claim'&&Engine.biological(s)<18?'disabled':''}><span><b>${label}</b><small>${hint}</small></span></button>`).join('')}</div><p class="belief-note">เลือกได้หนึ่งเรื่องต่อช่วง 3 เดือน · การประกาศเขตเริ่มได้เมื่อโตเต็มวัย</p><button class="secondary" id="openNativeExchange">วิถีถิ่นและการแลกเปลี่ยนกับชุมชน →</button>`:''}<p id="raceWayError" class="belief-error" role="status"></p><button class="secondary" id="raceYearFocus">เลือกโฟกัสปีนี้ตามทางที่อยากลอง →</button><h3>ทางที่เคยเลือก</h3>${r.history.map(h=>`<p>อายุ ${h.age} · ${esc(p.paths[h.stance])}</p>`).join('')||'<p class="belief-note">ยังไม่ได้ผูกทางไว้กับความคาดหวังใด</p>'}</section>`);document.querySelectorAll('[data-race-stance]').forEach(b=>b.onclick=()=>{if(RaceDrives.choose(s,b.dataset.raceStance))refresh(ways)});document.querySelectorAll('[data-native-action]').forEach(b=>b.onclick=()=>{if(RaceDrives.act(s,b.dataset.nativeAction))refresh(ways);else $('#raceWayError').textContent='ร่างหรือแหล่งถิ่นยังไม่พร้อมสำหรับทางนี้'});$('#raceYearFocus').onclick=LifeUI.focus;if($('#openNativeExchange'))$('#openNativeExchange').onclick=EcologyUI.open}
 function faith(){const s=state,f=FaithWorld.ensure(s),g=FaithWorld.god(f.chosen),a=f.active,locked=!FaithWorld.ready(s)||Engine.biological(s)<6;modal(`<section class="belief-dialog"><span class="eyebrow">ศรัทธาและคำบัญชา · ปี ${WorldTimeline.year(s)}</span><h2>${g?esc(g.name):'จะรับฟังผู้ใดในโลกนี้?'}</h2><p class="belief-note">เทพและศาสดาเหล่านี้มีตัวตนและเปลี่ยนโลกได้ การนับถือเปิดโอกาสพบและรับเควสต์ เมื่อคำขอมาถึงคุณยังเลือกทำ ตีความใหม่ หรือปฏิเสธได้</p>${g?`<div class="faith-current" style="--deity:${g.colour}"><span class="eyebrow">${esc(g.deity)}</span><h3>แรงศรัทธา ${Math.round(f.devotion)}/100</h3><p>${esc(g.teaching)}</p>${a?`<p><b>เควสต์บท ${a.stage+1}/3</b> · ${a.progress>=4?'พร้อมรับฟังคำขอ':'กำลังดำเนินชีวิตระหว่างบท · '+a.progress+'/4 ช่วง'}</p><p>${esc(a.stage===0?g.request:a.stage===1?g.trial:g.tension)}</p>`:`<p>${f.completed.some(x=>x.id===g.id)?'สิ่งที่เคยตอบต่อเทพองค์นี้อยู่ในบันทึกแล้ว':'คำขออาจมาถึงหลังคุณผ่านเวลาและเติบโตพอรับผลของมัน'}</p>`}<button class="secondary" id="leaveFaith" ${locked?'disabled':''}>ออกจากพันธะศรัทธานี้</button></div>`:''}${f.effects.length?`<h3>ร่องรอยที่พิธียังทิ้งไว้</h3>${f.effects.map(e=>`<p><b>${esc(FaithWorld.god(e.id).boon)}</b><br>${esc(KINGDOMS[e.realm][0])} · ถึงปี ${e.until} · ${e.delta>0?'แรงกดดันเพิ่ม':'แรงกดดันลด'} ${Math.round(Math.abs(e.delta)*100)} จุด · การค้า ${e.trade>0?'+':''}${Math.round(e.trade*100)} จุด${e.benefitRealm!==undefined?'<br>ผู้ได้ประโยชน์: '+esc(KINGDOMS[e.benefitRealm][0]):''}</p>`).join('')}`:''}<div class="faith-catalog">${FaithLore.map(deity=>`<article class="faith-card ${f.chosen===deity.id?'selected':''}" style="--deity:${deity.colour}"><div class="faith-card-heading"><canvas width="72" height="56" data-deity-icon="${deity.id}" aria-label="ตราของ${esc(deity.deity)}"></canvas><div><h3>${esc(deity.name)}</h3><span>${esc(deity.deity)}</span></div></div><p>${esc(deity.teaching)}</p><details><summary>สิ่งที่เคยเกิดขึ้นและความขัดแย้งในสำนัก</summary><p>${esc(deity.proof)}</p><p>${esc(deity.tension)}</p><p><b>ถิ่นปรากฏ:</b> ${esc(KINGDOMS[deity.realm][0])}</p></details><small class="belief-affinity">${deity.affinities.includes(s.race)?'พบผู้รับฟังวิถีนี้ในหมู่เผ่าของคุณ':'รับผู้ติดตามต่างเผ่าเช่นเดียวกัน'}</small><button class="secondary" data-follow-deity="${deity.id}" ${locked||f.chosen===deity.id||f.lastJoinYear===WorldTimeline.year(s)?'disabled':''}>${f.chosen===deity.id?'กำลังรับฟังวิถีนี้':'เลือกนับถือ'}</button></article>`).join('')}</div><p class="belief-note">เริ่มศรัทธาใหม่ได้ปีละครั้ง · ออกจากศรัทธาได้เมื่ออ่านคำถามที่ค้างอยู่จบ · การเปลี่ยนศรัทธาไม่ลบผลที่เคยทำต่อโลก</p><h3>สิ่งที่เคยตอบกลับ</h3>${f.history.slice(0,12).map(h=>`<p><b>ปี ${h.year} · ${esc(h.title)}</b><br>${esc(h.text)}</p>`).join('')||'<p class="belief-note">ยังไม่มีพันธะหรือคำบัญชาที่ตอบไว้</p>'}</section>`);document.querySelectorAll('[data-follow-deity]').forEach(b=>b.onclick=()=>{if(FaithWorld.follow(s,b.dataset.followDeity))refresh(faith)});if($('#leaveFaith'))$('#leaveFaith').onclick=()=>{if(FaithWorld.follow(s,null))refresh(faith)};document.querySelectorAll('[data-deity-icon]').forEach(c=>drawSigil(c,FaithWorld.god(c.dataset.deityIcon)))}
 function drawSigil(canvas,g){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#e6e8db';c.fillRect(0,0,72,56);c.fillStyle=g.colour;const r=(x,y,w,h)=>c.fillRect(x,y,w,h),id=g.sigil;r(34,11,4,33);if(id==='sun'||id==='eye'){for(let i=0;i<5;i++)r(20+i*6,21-Math.abs(i-2)*2,5,18+Math.abs(i-2)*4);c.fillStyle='#e9e5cd';r(31,22,10,10)}else if(id==='horn'||id==='wing'){for(let i=0;i<4;i++){r(14+i*5,10+i*5,5,13);r(53-i*5,10+i*5,5,13)}}else if(id==='wave'){for(let i=0;i<7;i++)r(12+i*7,22+i%3*4,8,4);r(19,38,35,3)}else if(id==='root'){for(let i=0;i<4;i++){r(17+i*9,15+i%2*4,5,12);r(18+i*9,35+i%2*3,4,9)}}else if(id==='crown'){r(16,29,42,9);for(let i=0;i<3;i++)r(16+i*18,16-i%2*6,6,17)}else if(id==='anvil'){r(15,21,45,7);r(26,28,21,13);r(20,41,33,4)}else{r(22,15,22,29);c.fillStyle='#e6e8db';r(30,10,19,29)}r(12,48,48,2)}
 return {panel,bind,ways,faith,drawSigil};
})();
